class Solution:
    def isValidBST(self, root: Optional[TreeNode]) -> bool:
        prev = float('-inf') # 相当于我们在中序遍历序列
        stk = []
        node = root
        while stk or node:
            while node:
                stk.append(node)
                node = node.left
            node = stk.pop()
            if node.val <= prev:
                return False
            prev = node.val
            node = node.right
        return True
